    // padding
    uint8_t buf[128];
    size_t rem = len - i;
    memcpy(buf, data+i, rem);
    buf[rem] = 0x80;
    size_t total = rem + 1;
    if (total > 56) {
        memset(buf+total, 0, 64-total);
        sha256_compress(state, buf);
        memset(buf, 0, 56);
        total = 0;
    } else {
        memset(buf+total, 0, 56-total);
    }
    uint64_t bitlen = (uint64_t)len * 8;
    for (int j=0;j<8;j++) buf[56+j] = (uint8_t)(bitlen >> (56-8*j));
